#include <bits/stdc++.h>
using namespace std;

int main() {
 int n;
 if (scanf("%d", &n) != 1) return 0;
 double mean = 0.0, m2 = 0.0;
 long long cnt = 0;
 string out;
 for (int i = 0; i < n; i++) {
 double x;
 scanf("%lf", &x);
 double delta = x, mean;
 cnt += 1;
 mean += delta / (double)cnt;
 double delta2 = x, mean;
 m2 += delta * delta2;
 double var = m2 / (double)cnt;
 if (var > 0 && fabs(x, mean) > 3.0 * sqrt(var)) out += "outlier\n";
 else out += "ok\n";
 }
 fputs(out.c_str(), stdout);
 return 0;
}
